#!/usr/bin/env bash
# Builds what the Android app loads: shellwing-mobile as a shared library for
# phones (arm64-v8a) and the emulator (x86_64), and the Kotlin that calls it,
# generated by UniFFI.
#
#   scripts/build_android.sh            release libraries
#   scripts/build_android.sh --debug    quicker to build, slower to run
#
# Writes android/app/src/main/jniLibs/<abi>/ and
# android/app/build/generated/uniffi/ (neither is committed). Needs the NDK
# (ANDROID_NDK_HOME, or one under ~/Android/Sdk/ndk), cargo-ndk
# (cargo install cargo-ndk), Zig 0.17 on PATH, and the two targets:
#   rustup target add aarch64-linux-android x86_64-linux-android
# No armv7 or x86: libghostty-vt builds for 64-bit Android only.
set -euo pipefail

cd "$(dirname "$0")/.."
ROOT="$PWD"
PROFILE=release
FLAG=--release
if [[ "${1:-}" == "--debug" ]]; then
	PROFILE=debug
	FLAG=
fi

if [[ -z "${ANDROID_NDK_HOME:-}" ]]; then
	ANDROID_NDK_HOME="$(ls -d "${ANDROID_HOME:-$HOME/Android/Sdk}"/ndk/* 2>/dev/null | sort -V | tail -1)"
fi
[[ -d "$ANDROID_NDK_HOME" ]] || { echo "no Android NDK: set ANDROID_NDK_HOME" >&2; exit 1; }
export ANDROID_NDK_HOME
# The oldest Android the app runs on (android/app/build.gradle.kts says the same).
API=28
CARGO="${CARGO:-cargo}"
APP="$ROOT/android/app"
OUT="$APP/build/generated/uniffi"

# A cdylib here only: the crate stays a static library for iOS, whose linker
# would need every system library a shared one does. libc++ goes beside it,
# for libghostty-vt's C++. Not stripped: UniFFI reads the library's metadata
# from its symbols below, and the Android build strips it when it packages it.
echo "building shellwing-mobile for arm64-v8a and x86_64 ($PROFILE)"
rm -rf "$APP/src/main/jniLibs"
CARGO_PROFILE_RELEASE_STRIP=false \
	"$CARGO" ndk -t arm64-v8a -t x86_64 -P "$API" --link-libcxx-shared -o "$APP/src/main/jniLibs" \
	rustc -p shellwing-mobile --lib $FLAG --crate-type cdylib
# cargo-ndk copies every shared library it finds; only these two are loaded.
find "$APP/src/main/jniLibs" -name '*.so' ! -name libshellwing_mobile.so ! -name libc++_shared.so -delete

# The Kotlin side, read from the library's own metadata, so it always
# matches what was built.
rm -rf "$OUT"
"$CARGO" run -q -p shellwing-mobile --features bindgen --bin uniffi-bindgen -- \
	generate --library "target/x86_64-linux-android/$PROFILE/libshellwing_mobile.so" \
	--language kotlin --out-dir "$OUT" --no-format
echo "built $APP/src/main/jniLibs and $OUT"
